package com.bank.init;

import java.math.BigDecimal;
import java.util.logging.*;

public class StaticInitFailureDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // --- Failing case: static block throws during initialization ---
        try {
            // First touch of AccountPolicy triggers its static block, which throws.
            log.info(() -> "Threshold = " + AccountPolicy.getThreshold());
        } catch (ExceptionInInitializerError e) {
            log.log(Level.SEVERE, "Class init failed, root cause below", e.getCause());
        }

        // Second touch of the SAME broken class → NoClassDefFoundError.
        try {
            BigDecimal t = AccountPolicy.getThreshold();
        } catch (Throwable t) {
            log.severe(() -> "Second use throws: " + t.getClass().getSimpleName());
        }

        // --- Corrected case: robust parsing, class initializes cleanly ---
        log.info(() -> "SafePolicy threshold = " + SafePolicy.getThreshold());
    }
}

// ─── Would be AccountPolicy.java in a real project (the BROKEN version) ───
class AccountPolicy {
    private static final BigDecimal MIN_BALANCE;
    static {
        // Simulated malformed config value -> throws NumberFormatException.
        String config = "ONE_THOUSAND"; // should have been "1000"
        MIN_BALANCE = new BigDecimal(config); // throws here, fails class init
    }
    static BigDecimal getThreshold() { return MIN_BALANCE; }
}

// ─── Would be SafePolicy.java in a real project (the FIXED version) ───
class SafePolicy {
    private static final BigDecimal MIN_BALANCE;
    static {
        // Robust: validate and fall back to a safe default instead of crashing.
        String config = System.getProperty("bank.minBalance", "1000");
        BigDecimal parsed;
        try {
            parsed = new BigDecimal(config);
        } catch (NumberFormatException ex) {
            parsed = new BigDecimal("1000"); // safe default, no init failure
        }
        MIN_BALANCE = parsed;
    }
    static BigDecimal getThreshold() { return MIN_BALANCE; }
}
